import {Studio as V3Studio,decodeAnimation} from './store.js';
import {readJson,seal,sha,canonical,checkGenome,toAscii} from './engine.js';
import {upgradeV45,FRAMINGS} from './fusion-v45.js';
import {AsciiDisplay} from './ascii-display.js';
export class Studio extends V3Studio{
 async init(){await super.init();this.registry45=await readJson('/data/traits-v45.json');this.recipes45=await readJson('/data/recipes-v45.json');this.audit45=await readJson('/v45/reports/collection-audit.json').catch(()=>null);this.catalog45=await readJson('/v45/collection/catalog.json').catch(()=>[]);this.experiments45=await readJson('/v45/experiments/index.json').catch(()=>({items:[]}));this.report45=await readJson('/v45/reports/experiments.json').catch(()=>null);this.blocks45=new Map();if(this.audit45?.passed&&this.audit45?.visual_review_approved&&this.catalog45.length===3333)this.release='v45';return this;}
 catalog(){return this.release==='v45'?this.catalog45:super.catalog();}
 setRelease(r){if(r==='v45'){if(!(this.audit45?.passed&&this.audit45?.visual_review_approved))throw Error('V4.5 release validation is still running.');this.release=r;return this.catalog();}return super.setRelease(r);}
 async item45(e){
  if(!Number.isInteger(e)||e<1||e>3333)throw Error('Invalid edition.');const b=Math.floor((e-1)/100);if(!this.blocks45.has(b))this.blocks45.set(b,readJson('/v45/collection/block-'+String(b).padStart(2,'0')+'.json.gz'));
  const a=(await this.blocks45.get(b)).find(r=>r.edition===e);if(!a||await sha(a.ascii)!==a.metadata.canonical_hash)throw Error('V4.5 artwork integrity failure.');return this.packet45(a,'V45E'+e);
 }
 packet45(a,id){const m=a.metadata,g=a.genome||{...m,genome_version:'web-4.5.0',fingerprint:m.genome_fingerprint,grid:m.native_grid||m.render_resolution,categories:m.attributes,animation:m.animation,motion:m.animation.motion,source_concepts:m.source_concepts,parameters:m.parameters,modifiers:m.modifiers};const p={id,genome:g,dna:a.dna,ascii:a.ascii,luminance:a.luminance,metadata:m,quality:m.quality,operators:g.scene||[],grid:g.grid,preview:m.image||'/v45/experiments/'+id+'.png',record45:a,performance:{backend:'CUDA · V4.5 canonical',render_ms:null}};this.cache.set(p.id,p);return p;}
 async experiment45(id){if(!/^E\d{3}$/.test(id))throw Error('Invalid experiment.');const a=await readJson('/v45/experiments/'+id+'.json.gz');await checkGenome(a.genome);if(await sha(a.ascii)!==a.metadata.canonical_hash)throw Error('Experiment integrity failure.');const p=this.packet45(a,id);p.experimental45=id;return p;}
 async animation(p,progress){if(p.record45)return decodeAnimation(await readJson(p.experimental45?'/v45/experiments/'+p.experimental45+'.frames.json.gz':'/v45/collection/animations/'+String(p.metadata.edition).padStart(4,'0')+'.frames.json.gz'));if(p.genome.genome_version==='web-4.5.0'){const g=p.genome,total=g.animation.fps*g.animation.seconds,out={version:'4.5.0',grid:g.grid,presentation:[600,600],fps:g.animation.fps,seconds:g.animation.seconds,profile:g.animation.name,frames:[],luminance:[]};for(let i=0;i<total;i++){const data=await this.engine.frame(p.base,g,i);out.frames.push(toAscii(data));out.luminance.push(Array.from({length:data.length/12},(_,j)=>data[j*12+1]));progress?.(i+1,total);}return out;}return super.animation(p,progress);}
 async generate(o){
  if(o.version!=='4.5.0')return super.generate(o);
  const selected=o.categories||{},old=Object.fromEntries(Object.entries(selected).filter(([,id])=>id.startsWith('V3.'))),base=await this.prepareV3({...o,version:'3.0.0',grid:50,categories:old});
  let g=await seal(upgradeV45(base,this.registry45,{grid:o.grid||80,categories:selected,framing:o.framing,motionIntensity:o.motionIntensity})),p;
  if(this.engine.backend==='CUDA'){
   const a=await this.engine.native.request('fit',{genome:g});g=a.genome;await checkGenome(g);this.engine.lastMs=a.render_ms;this.engine.metrics.renders++;const data=new Float32Array(a.cells);p={id:g.fingerprint,genome:g,ascii:toAscii(data),luminance:Array.from({length:data.length/12},(_,i)=>data[i*12+1]),grid:g.grid,base:data,data,preview:a.preview,operators:g.scene,quality:a.quality,repair_log:a.repairs,performance:{backend:'CUDA',render_ms:a.render_ms,gpu_ms:a.gpu_ms}};
  }else{
   // Browser live rendering remains a separate WebGPU/CPU preview backend.
   // Published images/timelines always retain their measured CUDA canonicals.
   for(let i=0;i<4;i++){const data=await this.engine.render(g),w=g.grid[0],active=[];for(let j=0;j<w*w;j++)if(data[j*12]!==32&&g.scene[Math.max(0,Math.round(data[j*12+10])-1)]?.[14]!==4)active.push(j);if(!active.length)throw Error('No visible subject.');const xs=active.map(j=>j%w),ys=active.map(j=>Math.floor(j/w)),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),extent=Math.max(xmax-xmin+1,ymax-ymin+1)/w;if(Math.abs(extent-.8)<.035)break;g.config[0]=Math.max(1.2,Math.min(8,g.config[0]*extent/.8));g=await seal(g);}
   p=await this.browserPacket45(g);
  }
  p.metadata=this.metadata45(p);p.metadata.canonical_hash=await sha(p.ascii);if(o.encryption==='AES-256-GCM')p.dna=await this.encrypt45(g,o.hiddenMessage);this.cache.set(p.id,p);return p;
 }
 metadata45(p){const g=p.genome;return {...this.metadataV3(p),name:'NULL GENESIS V4.5 LAB',release:'v45-candidate',native_grid:g.grid,presentation_size:[600,600],encoder_version:g.encoder.version,encoder_details:g.encoder,framing_mode:g.composition.mode,composition:g.composition,density_budget:g.density_budget,frame_occupancy:p.quality?.dimension_occupancy,quality_record:p.quality?{metrics:p.quality,repair_log:p.repair_log||[]}:null,image:p.preview};}
 async squarePreview(p,size=600){const c=document.createElement('canvas'),display=new AsciiDisplay(c,await AsciiDisplay.font());display.draw(p.ascii,p.luminance,p.grid,size);const png=c.toDataURL('image/png');display.dispose();return png;}
 async browserPacket45(g){await checkGenome(g);const data=await this.engine.render(g),p={id:g.fingerprint,genome:g,ascii:toAscii(data),luminance:Array.from({length:data.length/12},(_,i)=>data[i*12+1]),grid:g.grid,base:data,data,operators:g.scene,performance:{backend:this.engine.backend+' · browser preview',render_ms:this.engine.lastMs}};p.preview=await this.squarePreview(p);return p;}
 async regenerate(g,a=false){if(g.genome_version!=='web-4.5.0')return super.regenerate(g,a);await checkGenome(g);let p;if(this.engine.backend==='CUDA'){const a=await this.engine.native.request('render',{genome:g}),data=new Float32Array(a.cells);this.engine.lastMs=a.render_ms;this.engine.metrics.renders++;p={id:g.fingerprint,genome:g,ascii:toAscii(data),luminance:Array.from({length:data.length/12},(_,i)=>data[i*12+1]),grid:g.grid,base:data,data,preview:a.preview,operators:g.scene,quality:a.quality,performance:{backend:'CUDA',render_ms:a.render_ms,gpu_ms:a.gpu_ms}};}else{p=await this.browserPacket45(g);}p.metadata=this.metadata45(p);p.metadata.canonical_hash=await sha(p.ascii);this.cache.set(p.id,p);return p;}
 async encrypt45(g,message=''){if(!this.key)throw Error('Load the V4.5 owner key in DNA Inspector.');const nonce=crypto.getRandomValues(new Uint8Array(12)),aad=new TextEncoder().encode('NULL-GENESIS/web-genome/v45/'+g.fingerprint),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv:nonce,additionalData:aad},this.key,new TextEncoder().encode(canonical({identity:g.fingerprint,genome:g,hidden_message:message||''}))),b64=b=>btoa(String.fromCharCode(...new Uint8Array(b)));return {version:45,algorithm:'AES-256-GCM',genome_version:g.genome_version,fingerprint:g.fingerprint,nonce:b64(nonce),aad:b64(aad),ciphertext:b64(cipher)};}
 async unlock45(e){if(!this.key)throw Error('Load the V4.5 owner key.');if(e.version!==45||e.algorithm!=='AES-256-GCM'||e.genome_version!=='web-4.5.0'||!/^[0-9a-f]{64}$/.test(e.fingerprint)||typeof e.ciphertext!=='string'||e.ciphertext.length>1000000)throw Error('Invalid V4.5 envelope.');const decode=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0)),aad=decode(e.aad);if(new TextDecoder().decode(aad)!=='NULL-GENESIS/web-genome/v45/'+e.fingerprint||decode(e.nonce).length!==12)throw Error('Invalid authenticated context.');const payload=JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:decode(e.nonce),additionalData:aad},this.key,decode(e.ciphertext))));if(payload.identity!==e.fingerprint||payload.genome.fingerprint!==e.fingerprint)throw Error('DNA identity failure.');const p=await this.regenerate(payload.genome);p.dna=e;p.hiddenMessage=payload.hidden_message;return p;}
 async migrate(original,options={}){const input=original.genome||original;if(input.genome_version==='web-4.5.0')throw Error('This DNA already uses V4.5.');if(input.genome_version!=='web-3.0.0'){const p=await super.migrate(original,{...options,grid:50});return this.migrate(p,options);}await checkGenome(input);let g=await seal(upgradeV45(input,this.registry45,{grid:options.grid||80,seed:input.seed,framing:options.framing}));g.provenance.migrated_from={genome_version:input.genome_version,fingerprint:input.fingerprint,original_preserved:true};g=await seal(g);if(this.engine.backend==='CUDA'){const fitted=await this.engine.native.request('fit',{genome:g});g=fitted.genome;await checkGenome(g);}const p=await this.regenerate(g);if(input.encryption==='AES-256-GCM'||original.dna?.algorithm)p.dna=await this.encrypt45(g,options.hiddenMessage||original.hiddenMessage);return p;}
 async api(path,body){const u=new URL(path,location.origin);if(u.pathname==='/api/decode'&&body.envelope.version===45)return this.unlock45(body.envelope);if(u.pathname==='/api/config'){const c=await super.api(path,body);return {...c,registry45:this.registry45,recipes45:this.recipes45};}if(this.release==='v45'){if(u.pathname==='/api/item')return this.item45(Number(u.searchParams.get('edition')));if(u.pathname==='/api/analytics')return readJson('/v45/reports/analytics.json');if(u.pathname==='/api/audit')return this.audit45;if(u.pathname==='/api/reveal'){const p=body.edition?await this.item45(body.edition):this.cache.get(body.id);if(!p.genome.scene)throw Error('Unlock the encrypted DNA first.');return this.regenerate(p.genome);}}return super.api(path,body);}
}
